<?php
namespace App\Filament\Resources;
use App\Filament\Resources\ParentMeetingResource\Pages;use App\Models\ParentMeeting;use App\Models\StudyGroup;
use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class ParentMeetingResource extends Resource{protected static ?string $model=ParentMeeting::class;protected static bool $shouldRegisterNavigation=false;protected static ?string $modelLabel='собрание';protected static ?string $pluralModelLabel='Родительские собрания';public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('study_group_id')->label('Группа')->options(fn()=>StudyGroup::where('active',1)->orderBy('name')->pluck('name','id'))->searchable()->required(),Forms\Components\DateTimePicker::make('meeting_at')->label('Дата и время')->required(),Forms\Components\TextInput::make('topic')->label('Тема')->required(),Forms\Components\TextInput::make('protocol_number')->label('Протокол №'),Forms\Components\TextInput::make('attendees_count')->label('Присутствовало')->numeric(),Forms\Components\Textarea::make('agenda')->label('Повестка')->columnSpan('full'),Forms\Components\Textarea::make('decisions')->label('Решения')->columnSpan('full')])->columns(2);}public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('meeting_at')->label('Дата')->dateTime('d.m.Y H:i')->sortable(),Tables\Columns\TextColumn::make('group.name')->label('Группа'),Tables\Columns\TextColumn::make('topic')->label('Тема')->searchable(),Tables\Columns\TextColumn::make('protocol_number')->label('Протокол'),Tables\Columns\TextColumn::make('attendees_count')->label('Присутствовало')])->actions([Tables\Actions\EditAction::make()->label('Изменить'),Tables\Actions\Action::make('archive')->label('В архив')->color('danger')->requiresConfirmation()->action(fn($record)=>$record->update(['archived_at'=>now()]))]);}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->whereNull('archived_at');}public static function getPages():array{return['index'=>Pages\ListParentMeetings::route('/'),'create'=>Pages\CreateParentMeeting::route('/create'),'edit'=>Pages\EditParentMeeting::route('/{record}/edit')];}}
